?>
<div class="rounded-2xl border border-amber-200 bg-amber-50 p-6 text-center" data-hn-payment-identity-gate>
    <div class="text-sm font-black tracking-[0.14em] text-primary mb-3">VERIFIED BUSINESS PAYMENT ONLY</div>
    <div class="text-lg font-black text-primary"><?= esc($payment['display_name']) ?></div>

    <?php if ($payment['active']): ?>
        <p class="mt-3 text-sm text-gray-700 leading-relaxed">Use the secure HiredNext checkout below.</p>
        <a href="<?= esc($payment['url']) ?>" rel="noopener noreferrer" class="mt-5 inline-flex w-full items-center justify-center rounded-xl bg-accent px-5 py-4 font-bold text-white transition hover:opacity-90">Continue to payment →</a>
    <?php elseif (!empty($payment['temporary_qr_active'])): ?>
        <p class="mt-3 text-sm text-gray-700 leading-relaxed">Scan the QR below with Paytm or any UPI app to complete payment.</p>
        <div class="mx-auto mt-5 max-w-[360px] rounded-3xl border border-gray-200 bg-white p-5 shadow-sm">
            <img src="data:image/png;base64," alt="HiredNext payment QR" class="block h-auto w-full" loading="eager" decoding="sync">
        </div>
        <p class="mt-4 text-xs text-gray-500">After payment, submit the transaction reference below so the HiredNext team can verify it.</p>
    <?php else: ?>
        <p class="mt-3 text-sm text-gray-700 leading-relaxed"><strong>Secure online payment is temporarily unavailable.</strong></p>
    <?php endif; ?>

    <?php if ($amountLabel !== ''): ?><div class="mt-4 text-xl font-black text-primary"><?= esc($amountLabel) ?></div><?php endif; ?>
    <?php if ($secondaryLabel !== ''): ?><div class="mt-1 text-xs font-semibold text-gray-500"><?= esc($secondaryLabel) ?></div><?php endif; ?>
</div>
